#!/usr/bin/env python3
"""Extract exact functions from committed snapshots; never live host dependencies."""
from pathlib import Path
import re
v2=Path(__file__).resolve().parent.parent
base=v2/'integration/baseline/host/src-tauri/src/native_core/extensions'
prop=v2/'integration/proposed/host/src-tauri/src/native_core/extensions'
def function(s,name):
 m=re.search(r'^(?:(?:pub(?:\(super\))? )?)(?:async )?fn '+name+r'(?:<|\()',s,re.M)
 if not m:raise ValueError(name)
 end=re.search(r'^}',s[m.start():],re.M)
 return s[m.start():m.start()+end.end()]+'\n'
s=(base/'process_install.rs').read_text();l=(base/'launcher.rs').read_text()
constants=s[s.index('pub(super) const MAX_ARCHIVE'):s.index('// Shared by installer')]
body='''// Generated by capture-contract.py from the exact committed host snapshot.
// These tests compile actual validator/extractor/registry function bytes, not a handwritten port.
#[allow(dead_code, clippy::redundant_closure, clippy::nonminimal_bool)] mod contract {
mod launcher {use serde_json::Value; use std::collections::HashSet; use super::process_install;
'''+function(l,'bounded_text')+function(l,'validate')+'''}
pub mod process_install { use serde_json::Value; use sha2::{Sha256,Digest};use std::{collections::HashSet,path::{Path,PathBuf},io::{Read,Write}};
'''+constants+''.join(function(s,n) for n in ['component','relative','digest','validate','artifact_for','hash_file','regular','verify_files','extract'])+'''
pub fn check(m:&Value)->Result<(),String>{validate(m)}
pub fn artifact_check(m:&Value,target:&str)->Result<(),String>{artifact_for(m,target).map(|_|())}
pub fn unpack(bytes:&[u8],path:&Path)->Result<(),String>{extract(bytes,path)}
pub fn inventory(dir:&Path,m:&Value,a:&Value)->Result<(),String>{verify_files(dir,m,a).map(|_|())}
}
'''
for name,d in [('before',base),('after',prop)]:
 r=(d/'registry.rs').read_text();struct=r[r.index('pub(super) struct Installed'):r.index('\nfn slug')]
 body+='mod '+name+' {use serde_json::Value; use std::path::{Path,PathBuf,Component};\n'+struct+function(r,'fallback')+function(r,'icon_path')+function(r,'command_icon_path')+'''
pub fn probe(root:&Path)->Option<String>{let extension=Installed {id:"com.tezbar.native.qrcode-generator".into(),slug:"qrcode-generator".into(),path:root.join("canonical"),'''+('resource_path:root.join("version"),' if name=='after' else '')+'''manifest:serde_json::json!({"icon":"resources/command-icon.png"}),data_dir:root.into()};
assert_eq!(extension.path.join("preferences.json"),root.join("canonical/preferences.json"));
assert_eq!(icon_path(&extension),command_icon_path(&extension,&serde_json::json!({"icon":"resources/command-icon.png"})));
icon_path(&extension)}
}
'''
body+='''#[test]fn real_registry_before_after(){let t=tempfile::tempdir().unwrap();let p=t.path();std::fs::create_dir_all(p.join("version/resources")).unwrap();std::fs::write(p.join("version/resources/command-icon.png"),b"png").unwrap();assert!(before::probe(p).is_none());assert_eq!(after::probe(p).unwrap(),p.join("version/resources/command-icon.png").to_str().unwrap());}
#[test]fn real_manifest_positive_negative(){use serde_json::json;let good:serde_json::Value=serde_json::from_str(include_str!("../extension.json")).unwrap();assert!(process_install::check(&good).is_ok());assert!(process_install::artifact_check(&good,"aarch64-apple-darwin").is_err());for (key,value) in [("schemaVersion",json!(2)),("execution",json!("in-process")),("id",json!("com.tezbar.native.wrong")),("capabilities",json!(["imaginary.rpc"]))]{let mut v=good.clone();v[key]=value;assert!(process_install::check(&v).is_err());}let mut v=good.clone();v["commands"][0]["refreshMs"]=json!(1);assert!(process_install::check(&v).is_err());}
#[test]fn real_archive_positive_negative(){use std::io::Write;fn zip(entries:&[(&str,&[u8])])->Vec<u8>{let mut writer=zip::ZipWriter::new(std::io::Cursor::new(Vec::new()));for(name,bytes)in entries{writer.start_file(*name,zip::write::SimpleFileOptions::default()).unwrap();writer.write_all(bytes).unwrap();}writer.finish().unwrap().into_inner()}
let bytes=zip(&[("bin/qr",b"binary"),("resources/icon.png",b"png")]);let t=tempfile::tempdir().unwrap();assert!(process_install::unpack(&bytes,t.path()).is_ok());for name in ["../escape","/abs","a/../b","C:/path","a\\\\b","CON","a."]{let t=tempfile::tempdir().unwrap();assert!(process_install::unpack(&zip(&[(name,b"x")]),t.path()).is_err(),"{name}");}let t=tempfile::tempdir().unwrap();assert!(process_install::unpack(&zip(&[("A",b"x"),("a",b"x")]),t.path()).is_err());}
#[test]fn built_package_uses_actual_host_inventory(){let Ok(root)=std::env::var("QR_PACKAGE_ROOT")else{return;};let dir=std::path::Path::new(&root);let m:serde_json::Value=serde_json::from_slice(&std::fs::read(dir.join("extension.json")).unwrap()).unwrap();let meta:serde_json::Value=serde_json::from_slice(&std::fs::read(dir.parent().unwrap().join("artifact.json")).unwrap()).unwrap();assert!(process_install::inventory(dir,&m,&meta).is_ok());let mut bad=m.clone();bad["files"]["LICENSE"]=serde_json::json!("0".repeat(64));assert!(process_install::inventory(dir,&bad,&meta).is_err());}
}
'''
(v2/'tests/host_contract.rs').write_text(body)
